def normalized_spell_entry(
    spell: SpellEntry,
    *,
    source: SpellSource,
    casting_ability: AbilityType,
) -> SpellEntry:
    return replace(spell, source=source, castingAbility=casting_ability, components=list(spell.components))


def clone_spell_entry(spell: SpellEntry) -> SpellEntry:
    return replace(spell, components=list(spell.components))


def spell_description(metadata: SpellCatalogMetadata, spell: SpellEntry) -> str:
    casting_label = metadata.castingDuration.summary if metadata.castingDuration is not None else enum_label(spell.castingTime)
    range_label = spell.targeting.summary
    components_label = ", ".join(enum_label(component) for component in spell.components) if spell.components else "None"
    duration_label = spell.duration.summary
    details = [
        f"Spell lists: {', '.join(spell_list.value for spell_list in metadata.spellLists)}.",
        f"Casting time: {casting_label}.",
        f"Range: {range_label}.",
        f"Components: {components_label}.",
        f"Duration: {duration_label}.",
    ]
    if metadata.triggered:
        details.append("Casting has a special trigger.")
    if metadata.materialCost:
        details.append("Material component has a listed cost.")
    if metadata.materialConsumed:
        details.append("Material component is consumed.")
    return " ".join(details)



@dataclass(frozen=True)
class SpellCatalogRecord:
    entry: SpellEntry
    spellLists: tuple[SpellListType, ...]
    url: str
    triggered: bool = False
    material: bool = False
    materialCost: bool = False
    materialConsumed: bool = False


def spell_metadata_from_record(record: SpellCatalogRecord) -> SpellCatalogMetadata:
    return SpellCatalogMetadata(
        spellId=record.entry.id,
        spellLists=record.spellLists,
        url=record.url,
        castingDuration=record.entry.castingDuration,
        triggered=record.triggered,
        material=record.material,
        materialCost=record.materialCost,
        materialConsumed=record.materialConsumed,
    )


def spell_entry_from_record(record: SpellCatalogRecord) -> SpellEntry:
    metadata = spell_metadata_from_record(record)
    spell = clone_spell_entry(record.entry)
    return replace(spell, description=spell_description(metadata, spell))


def build_spell_catalog(records: tuple[SpellCatalogRecord, ...]) -> dict[SpellId, SpellEntry]:
    return {record.entry.id: spell_entry_from_record(record) for record in records}


def build_spell_metadata(records: tuple[SpellCatalogRecord, ...]) -> dict[SpellId, SpellCatalogMetadata]:
    return {record.entry.id: spell_metadata_from_record(record) for record in records}


